using namespace up;
namespace {unsigned checks=0;void check(bool value,const char* why){++checks;if(!value){std::fprintf(stderr,"FAIL UI REFRESH: %s\n",why);std::exit(1);}}
struct Record:Painter {struct Box{float x,y,w,h;uint32_t color;};std::vector<Box> boxes;std::vector<std::string> labels;unsigned sprites=0;std::vector<float> lines;
 void rect(float x,float y,float w,float h,uint32_t color)override{boxes.push_back({x,y,w,h,color});}void line(float x,float y,float xx,float yy,uint32_t)override{lines.insert(lines.end(),{x,y,xx,yy});}void circle(float,float,float,uint32_t)override{}void sprite(const Texture&,float,float,float,float,uint32_t)override{++sprites;}void sprite_region(const Texture&,float,float,float,float,float,float,float,float,uint32_t)override{++sprites;}void text(int,int,uint32_t,const char* value)override{labels.emplace_back(value);}bool has(const char* value){for(const auto& label:labels)if(label.find(value)!=std::string::npos)return true;return false;}};
}
unsigned ui_refresh_tests(){
 checks=0;
 {Game home;home.phase=Phase::Menu;home.menu_preview_checked=true;home.tutorial.enabled=false;home.continue_available=false;
 Input down;down.down=true;home.input(down,.05f);check(home.selection==2,"home D-pad reaches icon row without a saved run");
 Input confirm;confirm.confirm=true;home.input(confirm,.05f);check(home.paused,"home sound tile opens settings");
 home.paused=false;
 for(unsigned node=3;node<=5;++node){home.selection=node;home.profile_open=false;home.input(confirm,.05f);check(home.profile_open && home.profile_tab==(node==3?1:node==4?2:0),"home icon opens its corresponding records tab");}
 home.profile_open=false;home.selection=6;home.input(confirm,.05f);check(home.phase==Phase::Menu && !home.daily_open,"locked daily icon stays on menu");
 home.selection=6;home.input(Input(),.3f);Input right;right.right=true;home.input(right,.05f);check(home.selection==2,"home icon focus wraps inside icon row");
 Skin empty;Record layout;paint_scene(layout,empty,home,0,0);for(const auto& box:layout.boxes)check(box.x>=0&&box.y>=0&&box.x+box.w<=480.01f&&box.y+box.h<=272.01f,"home rectangles remain within PSP framebuffer");}

 {Skin icons;Record prompt;draw_ui_text(prompt,icons,0,0,14,0xffffffff,"{cross} {circle} {square} {triangle}");check(prompt.lines.size()>40 && !prompt.has("{cross}") && !prompt.has("Square"),"PSP face prompts draw geometry even without the private font");check(ui_text_width(icons,14,"{square}")==ui_text_width(icons,14,"{triangle}"),"face symbols reserve consistent measured space");check(ui_text_width(icons,14,"{select}")>ui_text_width(icons,14,"{L}"),"system and shoulder labels have measured symbol widths");}
 {Skin skin;Game g;g.phase=Phase::Shop;g.tutorial.enabled=true;g.snack_bar=true;g.tutorial.trigger("passives-2",0);g.tutorial.elapsed=10;Record offers;paint_scene(offers,skin,g,0,0);bool right_panel=false;for(const auto& b:offers.boxes)right_panel|=b.x==228 && b.y==62 && b.w==242 && b.h==184;check(right_panel,"snack-offer tutorial moves its panel to the opposite side of all three offers");g.tutorial.active=tutorial_count;g.tutorial.trigger("passives-3",0);g.tutorial.elapsed=10;Record owned;paint_scene(owned,skin,g,0,0);bool left_panel=false;for(const auto& b:owned.boxes)left_panel|=b.x==10 && b.y==62 && b.w==198 && b.h==184;check(left_panel,"owned-snack tutorial keeps the complete owned grid unobstructed");g.tutorial.active=tutorial_count;g.tutorial.trigger("shots-1",0);g.tutorial.elapsed=10;g.phase=Phase::Placement;Record shots;paint_scene(shots,skin,g,0,0);bool pips=false;for(unsigned i=0;i+3<shots.lines.size();i+=4)pips|=shots.lines[i]==203 && shots.lines[i+1]==1 && shots.lines[i+2]==295 && shots.lines[i+3]==1;check(pips,"shot tutorial highlights actual HUD pips rather than center-table score");g.tutorial.active=tutorial_count;g.tutorial.trigger("pocket-1",0);g.tutorial.elapsed=10;Ball cue;cue.cue=true;g.world.add(cue);Ball captured;captured.last_pocket_tick=1;captured.pocket_index=2;g.world.add(captured);Record pocket;paint_scene(pocket,skin,g,0,0);bool upper_panel=false;for(const auto& b:pocket.boxes)upper_panel|=b.x==20 && b.y==34 && b.w==440 && b.h==91;check(upper_panel,"bottom-pocket tutorial moves above its captured-pocket target");}

 {Skin empty;Game shop;shop.phase=Phase::Shop;shop.shop_focus=ShopFocus::Market;
 for(unsigned tier=0;tier<3;++tier)for(unsigned id=1;id<content_count;++id)if(ball_info(id).can_drop && rarity(id)==tier){shop.offers[tier]=id;shop.offer_items[tier]=default_item(id);break;}
 Record first;paint_scene(first,empty,shop,0,0);check(first.has("Common") && first.has("Uncommon") && first.has("Rare"),"shop visibly names each offered ball rarity");
 shop.ui_time=1;Record rotated;paint_scene(rotated,empty,shop,0,0);check(first.lines!=rotated.lines,"shop selection square rotates over UI time");
 shop.offer_items[0].mixed_with=shop.offers[1];Record mixed;paint_scene(mixed,empty,shop,0,0);check(mixed.has("Mixed"),"mixed offer displays its distinct rarity");
 shop.snack_bar=true;for(unsigned tier=0;tier<2;++tier)for(unsigned id=1;id<snack_count;++id)if(snack_rarity(id)==tier){shop.snack_offers[tier]=id;break;}
 Record snacks;paint_scene(snacks,empty,shop,0,0);check(snacks.has("Common") && snacks.has("Uncommon"),"snack offers visibly display rarity too");}

 check(shop_slot_position(0).y>shop_slot_position(1).y&&shop_slot_position(1).y>shop_slot_position(3).y&&shop_slot_position(3).y>shop_slot_position(6).y,"rack is inverted 4-3-2-1 triangle with first ball at point");
 for(unsigned i=0;i<15;++i){auto p=shop_slot_position(i);check(p.x>=218&&p.x<=472&&p.y>=40&&p.y<=238,"rack and reserve centers stay on inventory mat");}
 check(shop_vertical_slot(0,true)==0&&shop_vertical_slot(0,false)==1,"bottom of triangle exits down and aims up to adjacent rack row");check(shop_vertical_slot(6,false)==6&&shop_vertical_slot(13,false)==10,"top row and reserve navigation remain in correct groups");
 // Every interactive shop node must be reachable from every other node.
 for(unsigned start=0;start<25;++start){if(start==20)continue;bool seen[25]={};seen[start]=true;for(unsigned pass=0;pass<25;++pass)for(unsigned n=0;n<25;++n)if(seen[n])for(unsigned d=0;d<4;++d){int dx=d==0?-1:d==1?1:0,dy=d==2?-1:d==3?1:0;unsigned next=shop_neighbor(n,dx,dy);check(next!=20,"removed Sell never takes D-pad focus");seen[next]=true;}for(unsigned n=0;n<25;++n)if(n!=20)check(seen[n],"all remaining shop nodes remain reachable");}
 for(unsigned n=3;n<18;++n)for(unsigned d=0;d<4;++d){unsigned next=shop_neighbor(n,d==0?-1:d==1?1:0,d==2?-1:d==3?1:0,true);check(next>=3&&next<18,"merge/move stays in inventory");}
 check(shop_neighbor(0,0,1)==18&&shop_neighbor(18,1,0)==19&&shop_neighbor(19,-1,0)==18,"Roll and Play navigate directly without Sell");
 Game sale;sale.reset();sale.phase=Phase::Shop;sale.shop_focus=ShopFocus::Inventory;Input sell;sell.finish=true;sale.input(sell,.016f);check(sale.sell_pending,"Triangle still opens sale confirmation");
 Input no;no.cancel=true;sale.input(no,.016f);check(!sale.sell_pending&&sale.inventory_count==3,"cancelling sale keeps the ball");
 Game g;g.reset();g.money=g.round_start_money=0;g.score=20;g.target=6;g.shots=2;
 check(g.finish_round()&&g.round_summary&&g.phase==Phase::Shop,"finished round opens result overlay before shop");check(g.payout_base==4&&g.payout_bonus==4&&g.payout_shots==2&&g.money==10,"result uses original base, triangular excess conversion and one coin per unused shot");
 Input down;down.down=true;g.input(down,.016f);check(g.shop_focus==ShopFocus::Market,"result overlay blocks shop input behind it");for(unsigned i=0;i<200;++i)g.update(.05);check(g.payout_done()&&g.money==10,"payout display counts to completion without paying twice");
 Skin skin;Record result;paint_scene(result,skin,g,0,0);check(result.has("ROUND WON")&&result.has("20 / 6")&&result.has("+10$"),"result shows final score and round money earned");Input confirm;confirm.confirm=true;g.input(confirm,.016f);check(!g.round_summary&&g.money==10,"continue enters shop without awarding another payout");Record shop;paint_scene(shop,skin,g,0,0);check(shop.has("YOUR BUILD")&&shop.has("RESERVE")&&shop.has("Play"),"shop uses build, reserve and original-style Play grouping");
 g.shop_focus=ShopFocus::Inventory;g.inventory_selection=0;Input up;up.up=true;g.input(up,.016f);check(g.shop_focus==ShopFocus::Inventory&&g.inventory_selection==1,"D-pad up navigates actual triangle geometry");
 g.shop_focus=ShopFocus::Market;g.money=0;g.offers[0]=9;g.buy(0);Record error;paint_scene(error,skin,g,0,0);check(error.has("Not enough money"),"shop keeps error feedback visible after visual redesign");
 for(const auto& box:shop.boxes)check(!(box.y==100&&box.color==0xffe9e9e9),"shop price text has no background box");
 Record stroke;draw_outlined_ui_text(stroke,skin,10,20,14,0xffffffff,0xff000000,"42");check(stroke.labels.size()==5&&stroke.boxes.empty(),"outlined text renders stroke and foreground without a rectangle");

 g.next_round();check(!g.round_summary&&g.score_display==0,"new round resets visual score and result state");g.world.pockets[0].bonus=5;g.world.pockets[1].bonus=-3;Record table;paint_scene(table,skin,g,0,0);check(table.has("+5")&&table.has("-3"),"both pocket modifier signs are visible in their badges");
 for(const auto& box:table.boxes)check(!((box.y==22||box.y==218)&&(box.color==0xffe6eadf||box.color==0xff4545b5)),"pocket text has no background box");check(ui_text_width(skin,12,"123")>ui_text_width(skin,12,"1"),"label measurements grow with content");


 g.world.balls[1].def=builtin(9);g.world.events.push(EventKind::Wall,1,0,g.world.metrics.ticks);g.dispatch();bool popup=false;for(const auto& p:g.score_popups)popup|=p.life>0;check(popup,"scoring emits a floating original-style score badge");
 g=Game();g.reset();g.money=g.round_start_money=0;g.score=3;g.shots=2;g.finish_round();g.input(confirm,.016f);check(g.round_summary&&g.payout_done(),"first confirm fast-forwards payout rather than opening shop immediately");int money=g.money;g.input(confirm,.016f);check(!g.round_summary&&g.money==money,"second confirm continues with unchanged wallet");
 Game large;large.reset();large.phase=Phase::Shop;large.round_summary=true;large.last_round_won=true;large.score=large.target=large.money=99999999;large.round_earned=99999999;large.reveal_payout();Record bounded;paint_scene(bounded,skin,large,0,0);check(!bounded.has("99999999")&&bounded.has("100.0M"),"large result values use compact bounded numbers");check(!bounded.has("L / R power")&&!bounded.has("Square inspect"),"result modal suppresses gameplay prompts");
 Game inspect;inspect.reset();inspect.inspected=1;float power=inspect.power;Input shoulder;shoulder.more=true;inspect.input(shoulder,.05f);check(inspect.power==power,"inspection consumes controls without changing shot power");Input close;close.cancel=true;inspect.input(close,.016f);check(inspect.inspected==0,"Circle closes inspection");
 Game passive;passive.reset();passive.phase=Phase::Shop;passive.shop_focus=ShopFocus::Passive;passive.snacks[0]=1;Input open;open.confirm=true;passive.input(open,.016f);check(passive.passive_details,"focused passive opens full details");passive.input(close,.016f);check(!passive.passive_details&&passive.phase==Phase::Shop,"closing passive details preserves shop");
 check(snack_neighbor(3,1,0)==4&&snack_neighbor(3,0,1)==5&&snack_neighbor(5,0,-1)==3,"snack D-pad follows its 2x2 owned grid");
 auto portrait=shop_portrait_layout(485.0f/1126);check(std::fabs(portrait.width/(portrait.height/portrait.v_bottom)-485.0f/1126)<.00001f,"portrait preserves original aspect before clipping");check(portrait.y+portrait.height==149&&portrait.v_bottom<1,"portrait ends at counter rather than exposing arm cutoffs");
 Game roster;roster.reset();roster.phase=Phase::Shop;roster.shop_focus=ShopFocus::Inventory;roster.inventory_selection=0;roster.inventory[0].id=9;roster.inventory[0].mixed_with=11;auto before=roster.inventory[0];int cash=roster.money;roster.input(open,.016f);check(roster.roster_details&&!roster.reorder_pending,"X opens owned-ball abilities rather than starting move");Record card;paint_scene(card,skin,roster,0,0);check(card.has("Pinball")&&card.has("Gold")&&card.has("Ball/wall")&&card.has("Pocket"),"mixed roster details display both ability descriptions");roster.input(close,.016f);check(!roster.roster_details&&roster.money==cash&&roster.inventory[0].id==before.id,"closing owned details preserves inventory and money");roster.input(open,.016f);Input move;move.inspect=true;roster.input(move,.016f);check(roster.reorder_pending&&!roster.roster_details&&roster.reorder_source==0,"Square from details preserves move/swap access");
 Game sparse;sparse.reset();sparse.phase=Phase::Shop;sparse.roster_details=true;sparse.inventory_selection=6;sparse.inventory[6].id=9;sparse.inventory[7].id=0;sparse.inventory[8].id=11;Input browse;browse.right=true;sparse.input(browse,.016f);check(sparse.inventory_selection==8,"owned ability browsing skips empty slots");
 std::printf("Visual/result fidelity checks: %u\n",checks);return checks;}

